import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
import { evolvePath } from "@remotion/paths";

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily: montserratFamily } = loadMontserrat();



export type SmartphoneTrafficProps = Record<string, any>;

const SmartphoneTraffic: React.FC<SmartphoneTrafficProps> = ({
  backgroundColor = "#0ea5e9", // Sky blue default
  transparentBackground = false,
  durationInSeconds = 8,
  textLines = [
    "Your audience",
    "is searching.",
    "clicking.",
    "engaging.",
    "RIGHT NOW."
  ],
  graphColor = "#eab308", // Yellow default
  phoneColor = "#1e293b", // Dark slate default
  counterEndValue = 2400,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Phone Slide Animation
  const phoneSlideProgress = spring({
    frame: frame - 15, // Starts slightly after sequence begins
    fps,
    config: { damping: 14, stiffness: 90 },
  });
  
  // Phone moves from bottom off-screen to 45% down the canvas
  const phoneTop = interpolate(phoneSlideProgress, [0, 1], [height, height * 0.45]);

  // Graph and Counter Animation
  // Initiates as the phone settles (frames 30 to 90)
  const graphProgress = interpolate(frame, [30, 90], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const counterValue = interpolate(frame, [30, 90], [0, counterEndValue], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Sharp, dramatic traffic spike path
  const graphPath = "M 20 380 L 100 360 L 180 370 L 260 280 L 340 300 L 420 180 L 480 200 L 580 40";
  const evolution = evolvePath(graphProgress, graphPath);

  // Formats numbers nicely (e.g., 2400 -> "2.4K")
  const formattedCounter = new Intl.NumberFormat('en-US', {
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(counterValue);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: montserratFamily, overflow: "hidden" }}>
      
      {/* Background/Typography Layer */}
      <div style={{
        position: "absolute",
        top: height * 0.12,
        left: 100,
        right: 100,
        display: "flex",
        flexDirection: "column",
        gap: 24,
      }}>
        {textLines.map((line, i) => {
          // Staggered timing for each line
          const delay = 20 + i * 15;
          const slideIn = spring({
            frame: frame - delay,
            fps,
            config: { damping: 10, mass: 0.8 }, // Damping 10 creates the natural pulse/overshoot
          });
          
          const translateY = interpolate(slideIn, [0, 1], [60, 0]);
          const opacity = interpolate(slideIn, [0, 1], [0, 1], { extrapolateRight: "clamp" });
          // Maps 0->1 spring to 0.8->1.0 scale, carrying over the spring's overshoot for a pulse effect
          const scale = interpolate(slideIn, [0, 1], [0.8, 1]); 

          const isLastLine = i === textLines.length - 1;

          return (
            <div
              key={i}
              style={{
                fontSize: isLastLine ? 100 : 80,
                fontWeight: 900,
                color: "#ffffff",
                lineHeight: 1.1,
                opacity,
                transform: `translateY(${translateY}px) scale(${scale})`,
                transformOrigin: "left center", // Keeps left-aligned text anchored during pulse
                transition: "none",
              }}
            >
              {line}
            </div>
          );
        })}
      </div>

      {/* Foreground Smartphone Layer */}
      <div style={{
        position: "absolute",
        left: (width - 800) / 2, // Centered horizontally
        top: phoneTop,
        width: 800,
        height: height * 0.7, // Covers the remaining bottom area
        backgroundColor: phoneColor,
        borderRadius: "80px 80px 0 0",
        padding: "24px 24px 0 24px",
        boxShadow: "0 40px 100px rgba(0,0,0,0.4)",
        display: "flex",
        flexDirection: "column",
        transition: "none",
      }}>
        <div style={{
          flex: 1,
          backgroundColor: "#ffffff",
          borderRadius: "60px 60px 0 0",
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          transition: "none",
        }}>
          {/* Faux Hardware Notch / Top Bar */}
          <div style={{
            height: 60,
            width: "100%",
            backgroundColor: "#f8fafc",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            borderBottom: "2px solid #f1f5f9",
            transition: "none",
          }}>
            <div style={{ width: 160, height: 24, backgroundColor: phoneColor, borderRadius: 12 }} />
          </div>
          
          {/* App Screen Content */}
          <div style={{ padding: 60, flex: 1, display: "flex", flexDirection: "column", transition: "none" }}>
            <h2 style={{ fontSize: 44, color: "#64748b", margin: 0, fontWeight: 700 }}>Live Traffic</h2>
            
            <div style={{
              fontSize: 140,
              fontWeight: 900,
              color: graphColor,
              margin: "30px 0 60px 0",
              fontVariantNumeric: "tabular-nums", // Prevents horizontal jitter as numbers tick
              transition: "none",
            }}>
              {formattedCounter}
            </div>
            
            {/* Animated Graph Area */}
            <svg viewBox="0 0 600 400" style={{ width: "100%", overflow: "visible", flex: 1, transition: "none" }}>
              {/* Background Grid Lines */}
              {[100, 200, 300].map(y => (
                <line key={y} x1="0" y1={y} x2="600" y2={y} stroke="#f1f5f9" strokeWidth="4" />
              ))}
              
              {/* The Spiking Traffic Line */}
              <path
                d={graphPath}
                fill="none"
                stroke={graphColor}
                strokeWidth="24"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeDasharray={evolution.strokeDasharray}
                strokeDashoffset={evolution.strokeDashoffset}
                style={{ transition: "none" }}
              />
            </svg>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SmartphoneTraffic;